class Solution:
    def taskSchedulerII(self, tasks: List[int], space: int) -> int:
        cur = 0
        last = {}
        for t in tasks:
            cur = max(cur + 1, last.get(t, float('-inf')) + space + 1)
            last[t] = cur
        return cur

c.cpp:
class Solution {
public:
    long long taskSchedulerII(vector<int>& tasks, int space) {
        long long cur = 0;
        unordered_map<int, long long> last;
        for (int t : tasks) {
            auto it = last.find(t);
            long long bound = (it == last.end()) ? LLONG_MIN : it->second + space + 1LL;
            cur = max(cur + 1, bound);
            last[t] = cur;
        }
        return cur;
    }
};

c.java:
class Solution {
    public long taskSchedulerII(int[] tasks, int space) {
        long cur = 0;
        Map<Integer, Long> last = new HashMap<>();
        for (int t : tasks) {
            long bound = last.containsKey(t) ? last.get(t) + space + 1L : Long.MIN_VALUE;
            cur = Math.max(cur + 1, bound);
            last.put(t, cur);
        }
        return cur;
    }
}

