var taskSchedulerII = function(tasks, space) {
    let cur = 0;
    const last = new Map();
    for (const t of tasks) {
        const bound = last.has(t) ? last.get(t) + space + 1 : -Infinity;
        cur = Math.max(cur + 1, bound);
        last.set(t, cur);
    }
    return cur;
};
